window.OPUS_PAGES["050"] = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<title>Loading, Beautifully — 16 Loaders &amp; Micro-interactions</title>\n<meta name=\"description\" content=\"A curated gallery of sixteen original loading animations and micro-interactions built with CSS and SVG. Replay any of them, or copy its CSS with one click.\">\n<meta name=\"theme-color\" content=\"#141414\">\n<style>\n/* ================= page chrome (not part of the copyable loaders) ================= */\n:root{\n  --char:#141414;\n  --card:#1b1a19;\n  --card-2:#171615;\n  --line:rgba(244,241,222,.07);\n  --line-2:rgba(244,241,222,.14);\n  --cream:#f4f1de;\n  --mute:#a19d8c;\n  --dim:#6d6a60;\n  --terra:#e07a5f;\n  --sand:#f2cc8f;\n  --sage:#81b29a;\n  --slate:#3d405b;\n  --sans:\"Avenir Next\",\"Segoe UI\",\"Helvetica Neue\",Arial,\"Nimbus Sans\",\"Liberation Sans\",sans-serif;\n  --mono:ui-monospace,\"SF Mono\",\"JetBrains Mono\",Menlo,Consolas,\"Nimbus Mono PS\",\"DejaVu Sans Mono\",monospace;\n}\n*,*::before,*::after{box-sizing:border-box}\nhtml{background:var(--char);color-scheme:dark;-webkit-text-size-adjust:100%}\nbody{margin:0;background:var(--char);color:var(--cream);font-family:var(--sans);font-size:15px;line-height:1.55;-webkit-font-smoothing:antialiased;overflow-x:hidden}\nbody::before{content:\"\";position:fixed;inset:0;pointer-events:none;z-index:0;background:\n  radial-gradient(60% 50% at 12% 0%,rgba(224,122,95,.08),transparent 70%),\n  radial-gradient(50% 40% at 95% 8%,rgba(129,178,154,.06),transparent 70%)}\nbutton{font:inherit;color:inherit}\n:focus-visible{outline:2px solid var(--sand);outline-offset:3px;border-radius:8px}\n.wrap{position:relative;z-index:1;max-width:1360px;margin:0 auto;padding:0 clamp(16px,3.4vw,44px)}\n\n/* header */\n.masthead{display:grid;grid-template-columns:1.25fr 1fr;gap:clamp(24px,5vw,80px);align-items:end;padding:clamp(40px,7vh,84px) 0 clamp(28px,4.5vh,48px);border-bottom:1px solid var(--line)}\n.kicker{margin:0 0 18px;font-family:var(--mono);font-size:11px;letter-spacing:.22em;text-transform:uppercase;color:var(--mute);display:flex;align-items:center;gap:12px}\n.kicker b{display:inline-block;width:8px;height:8px;border-radius:2px;background:var(--terra);animation:kick 2.4s ease-in-out infinite}\n@keyframes kick{0%,100%{transform:rotate(0)}50%{transform:rotate(90deg);border-radius:50%}}\nh1{margin:0;font-weight:600;font-size:clamp(40px,6.4vw,92px);line-height:.98;letter-spacing:-.035em;color:var(--cream)}\nh1 em{font-style:normal;color:var(--sand)}\nh1 .nw{white-space:nowrap}\nh1 .dots{display:inline-flex;gap:.09em;margin-left:.06em;vertical-align:baseline}\nh1 .dots i{display:inline-block;width:.13em;height:.13em;border-radius:50%;background:var(--terra);animation:hop 1.3s cubic-bezier(.3,0,.3,1) infinite}\nh1 .dots i:nth-child(2){background:var(--sand);animation-delay:.14s}\nh1 .dots i:nth-child(3){background:var(--sage);animation-delay:.28s}\n@keyframes hop{0%,60%,100%{transform:translateY(0)}30%{transform:translateY(-.22em)}}\n.intro{margin:0 0 20px;color:var(--mute);font-size:16px;max-width:46ch}\n.intro strong{color:var(--cream);font-weight:600}\n.tools{display:flex;flex-wrap:wrap;align-items:center;gap:14px 18px}\n.swatches{display:flex;gap:6px;list-style:none;margin:0;padding:0}\n.swatches li{position:relative;width:30px;height:30px;border-radius:9px;background:var(--c);box-shadow:inset 0 0 0 1px rgba(255,255,255,.08)}\n.swatches li span{position:absolute;left:50%;top:calc(100% + 6px);transform:translate(-50%,-4px);font-family:var(--mono);font-size:9.5px;color:var(--mute);white-space:nowrap;opacity:0;transition:opacity .25s,transform .25s;pointer-events:none}\n.swatches li:hover span{opacity:1;transform:translate(-50%,0)}\n.pill{display:inline-flex;align-items:center;gap:9px;height:36px;padding:0 14px;border-radius:999px;border:1px solid var(--line-2);background:rgba(244,241,222,.03);font-family:var(--mono);font-size:11px;letter-spacing:.14em;text-transform:uppercase;cursor:pointer;transition:background .25s,border-color .25s}\n.pill:hover{background:rgba(244,241,222,.07);border-color:rgba(244,241,222,.24)}\n.pill svg{width:14px;height:14px;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}\n.count{font-family:var(--mono);font-size:11px;letter-spacing:.14em;text-transform:uppercase;color:var(--dim)}\n\n/* grid */\n.gallery{padding:clamp(24px,4vh,40px) 0 20px}\n.grid{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px}\n.card{--accent:var(--terra);position:relative;display:flex;flex-direction:column;border-radius:20px;background:linear-gradient(180deg,var(--card),var(--card-2));border:1px solid var(--line);overflow:hidden;transition:border-color .45s,transform .6s cubic-bezier(.2,.9,.25,1),box-shadow .6s}\n.card:hover{border-color:color-mix(in srgb,var(--accent) 45%,transparent);transform:translateY(-3px);box-shadow:0 22px 50px -24px color-mix(in srgb,var(--accent) 45%,transparent)}\n.stage{position:relative;height:212px;display:grid;place-items:center;overflow:hidden;isolation:isolate}\n.stage::before{content:\"\";position:absolute;inset:0;z-index:-1;background:\n  radial-gradient(circle at 1px 1px,rgba(244,241,222,.07) 1px,transparent 1.4px) 0 0/16px 16px;\n  -webkit-mask:radial-gradient(70% 70% at 50% 50%,#000,transparent);mask:radial-gradient(70% 70% at 50% 50%,#000,transparent)}\n.stage::after{content:\"\";position:absolute;inset:0;z-index:-1;background:radial-gradient(55% 50% at 50% 50%,color-mix(in srgb,var(--accent) 12%,transparent),transparent 70%);opacity:.0;transition:opacity .6s}\n.card:hover .stage::after{opacity:1}\n.meta{display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:12px;padding:13px 12px 13px 16px;border-top:1px solid var(--line)}\n.num{font-family:var(--mono);font-size:11px;color:var(--accent);letter-spacing:.06em;align-self:start;padding-top:2px}\n.card h3{margin:0;font-size:14.5px;font-weight:600;letter-spacing:-.005em;line-height:1.25}\n.kind{display:block;margin-top:3px;font-family:var(--mono);font-size:10px;letter-spacing:.06em;color:var(--dim)}\n.acts{display:flex;gap:6px}\n.act{position:relative;display:inline-flex;align-items:center;justify-content:center;gap:6px;height:32px;min-width:32px;padding:0 9px;border-radius:10px;border:1px solid var(--line);background:rgba(244,241,222,.02);cursor:pointer;font-family:var(--mono);font-size:10px;letter-spacing:.08em;color:var(--mute);transition:background .25s,border-color .25s,color .25s}\n.act:hover{background:rgba(244,241,222,.07);border-color:var(--line-2);color:var(--cream)}\n.act svg{width:14px;height:14px;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round;transition:transform .5s cubic-bezier(.3,1.4,.5,1)}\n.act.replay:hover svg{transform:rotate(-200deg)}\n.act.copy .ok{display:none}\n.act.copy.done{color:var(--sage);border-color:rgba(129,178,154,.45)}\n.act.copy.done .ok{display:block}\n.act.copy.done .ic{display:none}\n\n.footnote{display:flex;flex-wrap:wrap;justify-content:space-between;gap:10px;padding:28px 0 44px;border-top:1px solid var(--line);margin-top:28px;font-family:var(--mono);font-size:11px;letter-spacing:.1em;text-transform:uppercase;color:var(--dim)}\n\n/* toast + fallback dialog */\n.toast{position:fixed;left:50%;bottom:24px;z-index:30;display:flex;align-items:center;gap:10px;padding:11px 16px 11px 12px;border-radius:14px;background:#f4f1de;color:#141414;font-size:13px;font-weight:600;box-shadow:0 20px 40px -12px rgba(0,0,0,.6);transform:translate(-50%,24px) scale(.96);opacity:0;pointer-events:none;transition:transform .55s cubic-bezier(.2,1.4,.4,1),opacity .3s}\n.toast.on{transform:translate(-50%,0) scale(1);opacity:1}\n.toast i{display:grid;place-items:center;width:22px;height:22px;border-radius:50%;background:#81b29a}\n.toast i svg{width:12px;height:12px;fill:none;stroke:#141414;stroke-width:2.4;stroke-linecap:round;stroke-linejoin:round}\n.toast small{font-family:var(--mono);font-weight:400;font-size:10.5px;color:#5a574e;margin-left:4px}\ndialog{width:min(640px,calc(100vw - 32px));border:1px solid var(--line-2);border-radius:18px;background:#1b1a19;color:var(--cream);padding:18px}\ndialog::backdrop{background:rgba(10,10,10,.7)}\ndialog h2{margin:0 0 4px;font-size:16px}\ndialog p{margin:0 0 12px;color:var(--mute);font-size:13px}\ndialog textarea{width:100%;height:260px;resize:vertical;border-radius:12px;border:1px solid var(--line-2);background:#121212;color:var(--cream);font:12px/1.5 var(--mono);padding:12px}\ndialog .row{display:flex;justify-content:flex-end;gap:8px;margin-top:12px}\n\n/* global motion states */\n.all-paused .stage *,.all-paused .stage *::before,.all-paused .stage *::after,\n.stage.off *,.stage.off *::before,.stage.off *::after{animation-play-state:paused!important}\n\n@media (max-width:1100px){.grid{grid-template-columns:repeat(3,minmax(0,1fr))}}\n@media (max-width:860px){\n  .masthead{grid-template-columns:1fr;align-items:start}\n  .grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}\n}\n@media (max-width:560px){\n  .stage{height:156px}\n  .stage>*{scale:.78}\n  .meta{grid-template-columns:auto 1fr;padding:11px 10px 10px 12px;gap:4px 8px}\n  .acts{grid-column:1/-1;justify-content:flex-end}\n  .act{height:30px}\n  .kind{display:none}\n  .card h3{font-size:13px}\n  .card{border-radius:16px}\n  .intro{font-size:15px}\n  .swatches{flex-basis:100%}\n  .swatches li{width:26px;height:26px}\n}\n@media (prefers-reduced-motion:reduce){\n  .stage *,.stage *::before,.stage *::after{animation-iteration-count:1!important}\n  h1 .dots i,.kicker b{animation:none}\n  .card,.card:hover{transform:none;transition:border-color .3s}\n}\n</style>\n\n<!-- ================= the sixteen loaders: each block below is exactly what \"Copy CSS\" copies ================= -->\n<style id=\"css-blob\">\n.ld-blob{position:relative;width:88px;height:88px}\n.ld-blob span{position:absolute;inset:0;background:linear-gradient(140deg,#f2cc8f 0%,#e07a5f 52%,#a9503a 100%);background-size:220% 220%;border-radius:42% 58% 63% 37%/41% 44% 56% 59%;box-shadow:inset -10px -12px 22px rgba(61,64,91,.55),inset 10px 10px 18px rgba(244,241,222,.3),0 20px 40px -14px rgba(224,122,95,.6);animation:ld-blob-morph 7s ease-in-out infinite,ld-blob-sheen 7s ease-in-out infinite,ld-blob-float 3.5s ease-in-out infinite}\n.ld-blob span::after{content:\"\";position:absolute;left:21%;top:17%;width:26%;height:15%;border-radius:50%;background:rgba(244,241,222,.55);filter:blur(3px);transform:rotate(-26deg)}\n.ld-blob::after{content:\"\";position:absolute;left:12%;right:12%;bottom:-24px;height:10px;border-radius:50%;background:radial-gradient(closest-side,rgba(0,0,0,.55),transparent);animation:ld-blob-shadow 3.5s ease-in-out infinite}\n@keyframes ld-blob-morph{\n  0%,100%{border-radius:42% 58% 63% 37%/41% 44% 56% 59%}\n  25%{border-radius:61% 39% 45% 55%/55% 62% 38% 45%}\n  50%{border-radius:37% 63% 58% 42%/38% 48% 52% 62%}\n  75%{border-radius:55% 45% 36% 64%/62% 38% 62% 38%}\n}\n@keyframes ld-blob-sheen{0%,100%{background-position:0% 0%}50%{background-position:100% 100%}}\n@keyframes ld-blob-float{0%,100%{transform:translateY(-5px) rotate(-4deg)}50%{transform:translateY(5px) rotate(4deg)}}\n@keyframes ld-blob-shadow{0%,100%{transform:scaleX(.78);opacity:.55}50%{transform:scaleX(1);opacity:1}}\n</style>\n<style id=\"css-orbit\">\n.ld-orbit{position:relative;width:100px;height:100px}\n.ld-orbit s{position:absolute;left:50%;top:50%;width:10px;height:10px;margin:-5px;border-radius:50%;background:#f4f1de;box-shadow:0 0 14px rgba(244,241,222,.55)}\n.ld-orbit i{position:absolute;border-radius:50%;border:1px solid rgba(244,241,222,.08)}\n.ld-orbit .o1{inset:0;--c:#e07a5f}\n.ld-orbit .o2{inset:17px;--c:#f2cc8f}\n.ld-orbit .o3{inset:33px;--c:#81b29a}\n.ld-orbit b{position:absolute;inset:-1px;animation:ld-orbit-spin 1.9s cubic-bezier(.62,.06,.36,.94) infinite}\n.ld-orbit .o2 b{animation-duration:1.4s;animation-direction:reverse}\n.ld-orbit .o3 b{animation-duration:1.05s}\n.ld-orbit b::before{content:\"\";position:absolute;left:50%;top:-4px;width:8px;height:8px;margin-left:-4px;border-radius:50%;background:var(--c);box-shadow:0 0 8px var(--c)}\n.ld-orbit b:nth-child(1){animation-delay:-.16s}\n.ld-orbit b:nth-child(2){animation-delay:-.12s;opacity:.6}\n.ld-orbit b:nth-child(3){animation-delay:-.08s;opacity:.38}\n.ld-orbit b:nth-child(4){animation-delay:-.04s;opacity:.22}\n.ld-orbit b:nth-child(5){animation-delay:0s;opacity:.1}\n.ld-orbit b:nth-child(2)::before{transform:scale(.82)}\n.ld-orbit b:nth-child(3)::before{transform:scale(.66)}\n.ld-orbit b:nth-child(4)::before{transform:scale(.52)}\n.ld-orbit b:nth-child(5)::before{transform:scale(.4)}\n@keyframes ld-orbit-spin{to{transform:rotate(360deg)}}\n</style>\n<style id=\"css-check\">\n.ld-check{width:86px;height:86px;overflow:visible;animation:ld-check-pop 2.8s cubic-bezier(.65,0,.35,1) infinite}\n.ld-check .c,.ld-check .k{fill:none;stroke-linecap:round;stroke-linejoin:round}\n.ld-check .c{stroke:#f4f1de;stroke-width:2.2;stroke-dasharray:164;stroke-dashoffset:164;transform:rotate(-90deg);transform-origin:32px 32px;animation:ld-check-ring 2.8s cubic-bezier(.65,0,.35,1) infinite}\n.ld-check .k{stroke:#81b29a;stroke-width:4.2;stroke-dasharray:36;stroke-dashoffset:36;animation:ld-check-tick 2.8s cubic-bezier(.65,0,.35,1) infinite}\n.ld-check .g{fill:#81b29a;opacity:0;transform-origin:32px 32px;animation:ld-check-glow 2.8s ease-out infinite}\n@keyframes ld-check-ring{0%{stroke-dashoffset:164;opacity:1}36%{stroke-dashoffset:0}86%{stroke-dashoffset:0;opacity:1}100%{stroke-dashoffset:0;opacity:0}}\n@keyframes ld-check-tick{0%,36%{stroke-dashoffset:36;opacity:1}56%{stroke-dashoffset:0}86%{stroke-dashoffset:0;opacity:1}100%{stroke-dashoffset:0;opacity:0}}\n@keyframes ld-check-pop{0%,54%,70%,100%{transform:scale(1)}61%{transform:scale(1.07)}}\n@keyframes ld-check-glow{0%,52%{opacity:0;transform:scale(.6)}60%{opacity:.18}80%,100%{opacity:0;transform:scale(1.35)}}\n</style>\n<style id=\"css-fill\">\n@property --ld-fill-p{syntax:\"<integer>\";inherits:true;initial-value:0}\n.ld-fill{position:relative;width:96px;height:96px;--ld-fill-p:0;counter-reset:ld-p var(--ld-fill-p);animation:ld-fill-count 4.4s cubic-bezier(.45,.05,.35,1) infinite}\n.ld-fill .glass{position:absolute;inset:0;border-radius:50%;overflow:hidden;background:#1f1d1c;box-shadow:inset 0 0 0 2px rgba(244,241,222,.16),inset 0 -10px 20px rgba(0,0,0,.35)}\n.ld-fill .glass::after{content:\"\";position:absolute;left:18%;top:12%;width:22%;height:12%;border-radius:50%;background:rgba(244,241,222,.16);transform:rotate(-30deg)}\n.ld-fill i{position:absolute;left:-50%;width:200%;height:200%;top:calc(104% - var(--ld-fill-p) * 1.14%);animation:ld-fill-spin 6s linear infinite}\n.ld-fill .w1{background:#e07a5f;border-radius:42%}\n.ld-fill .w2{background:rgba(244,241,222,.2);border-radius:38%;margin-top:-7px;animation-duration:9s;animation-direction:reverse}\n.ld-fill .pct{position:absolute;inset:0;display:grid;place-items:center;font:600 18px/1 ui-monospace,\"SF Mono\",Menlo,Consolas,monospace;color:#f4f1de;text-shadow:0 1px 8px rgba(0,0,0,.35)}\n.ld-fill .pct::after{content:counter(ld-p) \"%\"}\n@keyframes ld-fill-count{0%{--ld-fill-p:0}78%,100%{--ld-fill-p:100}}\n@keyframes ld-fill-spin{to{transform:rotate(360deg)}}\n</style>\n<style id=\"css-fold\">\n.ld-fold{display:grid;grid-template-columns:repeat(3,22px);gap:4px;transform:rotate(45deg)}\n.ld-fold i{position:relative;width:22px;height:22px;transform-style:preserve-3d;animation:ld-fold-y 3s cubic-bezier(.7,0,.3,1) infinite;animation-delay:calc(var(--o) * .09s)}\n.ld-fold i.x{animation-name:ld-fold-x}\n.ld-fold i::before,.ld-fold i::after{content:\"\";position:absolute;inset:0;border-radius:3px;backface-visibility:hidden;-webkit-backface-visibility:hidden}\n.ld-fold i::before{background:#e07a5f}\n.ld-fold i::after{background:#81b29a;transform:rotateY(180deg)}\n.ld-fold i.x::after{transform:rotateX(180deg)}\n.ld-fold i:nth-child(even)::before{background:#f2cc8f}\n@keyframes ld-fold-y{0%,12%{transform:perspective(160px) rotateY(0)}32%,60%{transform:perspective(160px) rotateY(180deg)}80%,100%{transform:perspective(160px) rotateY(360deg)}}\n@keyframes ld-fold-x{0%,12%{transform:perspective(160px) rotateX(0)}32%,60%{transform:perspective(160px) rotateX(180deg)}80%,100%{transform:perspective(160px) rotateX(360deg)}}\n</style>\n<style id=\"css-breath\">\n.ld-breath{position:relative;width:104px;height:104px;display:grid;place-items:center}\n.ld-breath i{position:absolute;inset:14px;border-radius:50%;border:2px solid #81b29a;animation:ld-breath 4.8s ease-in-out infinite}\n.ld-breath i:nth-child(2),.ld-breath i:nth-child(3){border-width:1px;opacity:0;animation-name:ld-breath-echo}\n.ld-breath i:nth-child(3){animation-delay:.7s}\n.ld-breath span{position:absolute;font:500 10px/1 ui-monospace,\"SF Mono\",Menlo,Consolas,monospace;letter-spacing:.34em;text-indent:.34em;text-transform:uppercase;color:#f4f1de;opacity:0;animation:ld-breath-in 4.8s ease-in-out infinite}\n.ld-breath span+span{animation-name:ld-breath-out}\n@keyframes ld-breath{0%,100%{transform:scale(.6);border-width:7px;box-shadow:0 0 0 0 rgba(129,178,154,0)}50%{transform:scale(1);border-width:1.5px;box-shadow:0 0 30px 2px rgba(129,178,154,.35),inset 0 0 18px rgba(129,178,154,.2)}}\n@keyframes ld-breath-echo{0%,46%{transform:scale(1);opacity:0}52%{opacity:.5}100%{transform:scale(1.5);opacity:0}}\n@keyframes ld-breath-in{0%,6%{opacity:0}16%,40%{opacity:.85}50%,100%{opacity:0}}\n@keyframes ld-breath-out{0%,56%{opacity:0}66%,90%{opacity:.85}100%{opacity:0}}\n</style>\n<style id=\"css-helix\">\n.ld-helix{display:flex;gap:7px;height:70px;align-items:center}\n.ld-helix i{position:relative;width:7px;height:70px;animation-delay:calc(var(--i) * -.14s)}\n.ld-helix i::before{content:\"\";position:absolute;left:3px;top:12px;bottom:12px;width:1px;background:rgba(244,241,222,.28);animation:ld-helix-rung 1.9s linear infinite;animation-delay:inherit}\n.ld-helix b{position:absolute;left:0;top:31.5px;width:7px;height:7px;border-radius:50%;background:#e07a5f;animation:ld-helix-a 1.9s infinite;animation-delay:inherit}\n.ld-helix b+b{background:#81b29a;animation-name:ld-helix-b}\n@keyframes ld-helix-a{\n  0%{transform:translateY(-24px) scale(1);opacity:.9;animation-timing-function:ease-in}\n  25%{transform:translateY(0) scale(1.4);opacity:1;animation-timing-function:ease-out}\n  50%{transform:translateY(24px) scale(1);opacity:.9;animation-timing-function:ease-in}\n  75%{transform:translateY(0) scale(.55);opacity:.45;animation-timing-function:ease-out}\n  100%{transform:translateY(-24px) scale(1);opacity:.9}\n}\n@keyframes ld-helix-b{\n  0%{transform:translateY(24px) scale(1);opacity:.9;animation-timing-function:ease-in}\n  25%{transform:translateY(0) scale(.55);opacity:.45;animation-timing-function:ease-out}\n  50%{transform:translateY(-24px) scale(1);opacity:.9;animation-timing-function:ease-in}\n  75%{transform:translateY(0) scale(1.4);opacity:1;animation-timing-function:ease-out}\n  100%{transform:translateY(24px) scale(1);opacity:.9}\n}\n@keyframes ld-helix-rung{0%,50%,100%{transform:scaleY(1)}25%,75%{transform:scaleY(.04)}}\n</style>\n<style id=\"css-type\">\n.ld-type{display:inline-flex;align-items:center;font:500 21px/1 ui-monospace,\"SF Mono\",Menlo,Consolas,\"DejaVu Sans Mono\",monospace;color:#f4f1de;padding:10px 14px;border-radius:10px;background:#1f1d1c;box-shadow:inset 0 0 0 1px rgba(244,241,222,.08)}\n.ld-type .t,.ld-type .d{display:inline-block;overflow:hidden;white-space:nowrap;width:0}\n.ld-type .t{animation:ld-type-word 4.8s infinite}\n.ld-type .d{color:#e07a5f;animation:ld-type-dots 4.8s infinite}\n.ld-type .caret{display:inline-block;width:2px;height:1.05em;margin-left:2px;background:#f2cc8f;animation:ld-type-blink .8s steps(1) infinite}\n@keyframes ld-type-word{\n  0%{width:0;animation-timing-function:steps(7,end)}\n  28%{width:7ch}\n  84%{width:7ch;animation-timing-function:steps(7,end)}\n  98%,100%{width:0}\n}\n@keyframes ld-type-dots{\n  0%,30%{width:0;animation-timing-function:steps(3,end)}\n  48%{width:3ch}\n  56%{width:3ch;animation-timing-function:steps(1,end)}\n  60%{width:0;animation-timing-function:steps(3,end)}\n  74%{width:3ch}\n  80%{width:3ch;animation-timing-function:steps(1,end)}\n  82%,100%{width:0}\n}\n@keyframes ld-type-blink{0%,49%{opacity:1}50%,100%{opacity:0}}\n</style>\n<style id=\"css-pendulum\">\n.ld-pend{position:relative;width:130px;height:112px}\n.ld-pend .arc{position:absolute;left:0;top:0;width:130px;height:112px;overflow:visible}\n.ld-pend .arc path{fill:none;stroke:rgba(244,241,222,.12);stroke-width:1;stroke-dasharray:2 5}\n.ld-pend .pivot{position:absolute;left:50%;top:4px;width:8px;height:8px;margin-left:-4px;border-radius:50%;background:#f4f1de}\n.ld-pend .arm{position:absolute;left:50%;top:8px;width:2px;height:64px;margin-left:-1px;background:linear-gradient(#f4f1de,rgba(244,241,222,.4));transform-origin:50% 0;animation:ld-pend-swing 1.15s ease-in-out infinite alternate}\n.ld-pend .bob{position:absolute;left:50%;top:100%;width:22px;height:22px;margin:-2px 0 0 -11px;border-radius:50%;background:radial-gradient(circle at 35% 30%,#fff3d6,#f2cc8f 40%,#e07a5f 100%);box-shadow:0 6px 14px -4px rgba(224,122,95,.7)}\n.ld-pend .shadow{position:absolute;left:50%;bottom:0;width:26px;height:7px;margin-left:-13px;border-radius:50%;background:radial-gradient(closest-side,rgba(0,0,0,.6),transparent);animation:ld-pend-x 1.15s ease-in-out infinite alternate,ld-pend-s 2.3s linear infinite}\n@keyframes ld-pend-swing{from{transform:rotate(36deg)}to{transform:rotate(-36deg)}}\n@keyframes ld-pend-x{from{translate:-44px 0}to{translate:44px 0}}\n@keyframes ld-pend-s{\n  0%,50%,100%{scale:.62;opacity:.5;animation-timing-function:ease-out}\n  25%,75%{scale:1.05;opacity:1;animation-timing-function:ease-in}\n}\n</style>\n<style id=\"css-comet\">\n.ld-comet{position:relative;width:88px;height:88px;animation:ld-comet-spin 1.15s linear infinite}\n.ld-comet::before{content:\"\";position:absolute;inset:0;border-radius:50%;background:conic-gradient(from 0deg,rgba(224,122,95,0) 0deg,rgba(224,122,95,.06) 120deg,#e07a5f 300deg,#f2cc8f 355deg,rgba(242,204,143,0) 360deg);-webkit-mask:radial-gradient(farthest-side,transparent calc(100% - 7px),#000 calc(100% - 6px));mask:radial-gradient(farthest-side,transparent calc(100% - 7px),#000 calc(100% - 6px))}\n.ld-comet::after{content:\"\";position:absolute;inset:0;border-radius:50%;box-shadow:inset 0 0 0 6px rgba(244,241,222,.045)}\n.ld-comet i{position:absolute;left:50%;top:-1px;width:8px;height:8px;margin-left:-4px;border-radius:50%;background:#fff6e6;box-shadow:0 0 8px 3px rgba(242,204,143,.85),0 0 22px 7px rgba(224,122,95,.45)}\n.ld-comet b{position:absolute;inset:26px;border-radius:50%;border:1px dashed rgba(244,241,222,.14);animation:ld-comet-spin 6s linear infinite reverse}\n@keyframes ld-comet-spin{to{transform:rotate(360deg)}}\n</style>\n<style id=\"css-pixels\">\n.ld-pix{display:grid;grid-template-columns:repeat(8,12px);gap:6px}\n.ld-pix i{width:12px;height:12px;border-radius:3px;background:#3d405b;animation:ld-pix-wave 1.8s ease-in-out infinite;animation-delay:calc((var(--x) + var(--y)) * .09s - 2s)}\n@keyframes ld-pix-wave{\n  0%,100%{transform:scale(.38);background:#3d405b}\n  38%{transform:scale(1);background:#81b29a}\n  52%{transform:scale(1.1) translateY(-3px);background:#f2cc8f}\n  66%{transform:scale(.8);background:#e07a5f}\n}\n</style>\n<style id=\"css-book\">\n.ld-book{position:relative;width:112px;height:70px;perspective:340px}\n.ld-book::before{content:\"\";position:absolute;inset:-5px -6px -7px;border-radius:6px;background:#e07a5f;box-shadow:0 14px 26px -12px rgba(224,122,95,.7)}\n.ld-book .l,.ld-book .r,.ld-book b{position:absolute;top:0;bottom:0;width:50%;background:#f4f1de repeating-linear-gradient(180deg,transparent 0 9px,rgba(61,64,91,.16) 9px 10px) 9px 12px/calc(100% - 18px) calc(100% - 20px) no-repeat}\n.ld-book .l{left:0;border-radius:4px 0 0 4px;box-shadow:inset -10px 0 14px -8px rgba(61,64,91,.35)}\n.ld-book .r{right:0;border-radius:0 4px 4px 0;box-shadow:inset 10px 0 14px -8px rgba(61,64,91,.35)}\n.ld-book b{left:50%;border-radius:0 4px 4px 0;transform-origin:0 50%;animation:ld-book-flip 2.8s cubic-bezier(.55,.05,.3,1) infinite}\n.ld-book b::after{content:\"\";position:absolute;inset:0;border-radius:inherit;background:linear-gradient(90deg,rgba(61,64,91,.35),rgba(61,64,91,0));opacity:0;animation:ld-book-shade 2.8s cubic-bezier(.55,.05,.3,1) infinite;animation-delay:inherit}\n.ld-book b:nth-of-type(2){animation-delay:.22s}\n.ld-book b:nth-of-type(3){animation-delay:.44s}\n@keyframes ld-book-flip{0%{transform:rotateY(0);opacity:0}6%,10%{transform:rotateY(0);opacity:1}50%,88%{transform:rotateY(-180deg);opacity:1}100%{transform:rotateY(-180deg);opacity:0}}\n@keyframes ld-book-shade{0%,10%{opacity:0}30%{opacity:1}50%,100%{opacity:0}}\n</style>\n<style id=\"css-heart\">\n.ld-heart{position:relative;width:96px;height:96px;display:grid;place-items:center;border:0;padding:0;background:none;cursor:pointer;-webkit-tap-highlight-color:transparent}\n.ld-heart svg{width:52px;height:52px;overflow:visible}\n.ld-heart path{fill:rgba(224,122,95,0);stroke:#f4f1de;stroke-width:1.8;stroke-linejoin:round;transform-origin:16px 18px;animation:ld-heart-loop 3.2s infinite}\n.ld-heart i{position:absolute;left:50%;top:50%;width:7px;height:7px;margin:-3.5px;border-radius:50%;background:var(--c,#f2cc8f);opacity:0;transform:rotate(var(--a)) translateY(0) scale(.4);animation:ld-heart-spark 3.2s ease-out infinite}\n.ld-heart i:nth-of-type(3n+1){--c:#e07a5f}\n.ld-heart i:nth-of-type(3n+2){--c:#81b29a}\n.ld-heart s{position:absolute;inset:14px;border-radius:50%;border:2px solid #e07a5f;opacity:0;animation:ld-heart-ring 3.2s ease-out infinite}\n@keyframes ld-heart-loop{\n  0%,18%{transform:scale(1);fill:rgba(224,122,95,0);stroke:#f4f1de}\n  23%{transform:scale(.72);fill:rgba(224,122,95,0)}\n  31%{transform:scale(1.3);fill:#e07a5f;stroke:#e07a5f}\n  37%{transform:scale(.9)}\n  43%{transform:scale(1.07)}\n  49%,84%{transform:scale(1);fill:#e07a5f;stroke:#e07a5f}\n  94%,100%{transform:scale(1);fill:rgba(224,122,95,0);stroke:#f4f1de}\n}\n@keyframes ld-heart-spark{0%,27%{opacity:0;transform:rotate(var(--a)) translateY(0) scale(.4)}31%{opacity:1}48%,100%{opacity:0;transform:rotate(var(--a)) translateY(-40px) scale(.2)}}\n@keyframes ld-heart-ring{0%,27%{opacity:0;transform:scale(.4);border-width:6px}31%{opacity:.9}46%,100%{opacity:0;transform:scale(1.25);border-width:0}}\n/* clicked: a one-shot burst, then it stays liked */\n.ld-heart[aria-pressed=\"true\"] path{fill:#e07a5f;stroke:#e07a5f;animation:ld-heart-once .9s both}\n.ld-heart[aria-pressed=\"true\"] i{animation:ld-heart-spark-once .9s ease-out both}\n.ld-heart[aria-pressed=\"true\"] s{animation:ld-heart-ring-once .9s ease-out both}\n.ld-heart.was[aria-pressed=\"false\"] path{animation:none}\n.ld-heart.was[aria-pressed=\"false\"] i,.ld-heart.was[aria-pressed=\"false\"] s{animation:none;opacity:0}\n@keyframes ld-heart-once{0%{transform:scale(.72)}35%{transform:scale(1.3)}55%{transform:scale(.9)}75%{transform:scale(1.07)}100%{transform:scale(1)}}\n@keyframes ld-heart-spark-once{0%{opacity:0;transform:rotate(var(--a)) translateY(0) scale(.4)}15%{opacity:1}100%{opacity:0;transform:rotate(var(--a)) translateY(-40px) scale(.2)}}\n@keyframes ld-heart-ring-once{0%{opacity:0;transform:scale(.4);border-width:6px}15%{opacity:.9}100%{opacity:0;transform:scale(1.25);border-width:0}}\n</style>\n<style id=\"css-daynight\">\n.ld-dn{position:relative;width:108px;height:50px;border:0;padding:0;border-radius:999px;background:linear-gradient(180deg,#f7dcae,#f2cc8f 55%,#e9a877);cursor:pointer;overflow:hidden;isolation:isolate;box-shadow:inset 0 2px 6px rgba(0,0,0,.2),0 12px 26px -12px rgba(224,122,95,.7);transition:box-shadow .7s}\n.ld-dn::before{content:\"\";position:absolute;inset:0;z-index:-1;background:linear-gradient(180deg,#1d1f31,#3d405b);opacity:0;transition:opacity .7s}\n.ld-dn .knob{position:absolute;top:7px;left:7px;width:36px;height:36px;border-radius:50%;overflow:hidden;background:#fff4d8;box-shadow:0 0 0 6px rgba(255,244,216,.28),0 0 20px rgba(255,214,140,.9);transition:transform .75s cubic-bezier(.55,1.55,.4,1),background .6s,box-shadow .6s}\n.ld-dn .knob::after{content:\"\";position:absolute;top:-6px;left:-6px;width:34px;height:34px;border-radius:50%;background:#2a2c43;transform:translate(-36px,-10px) scale(.5);transition:transform .75s cubic-bezier(.5,1.3,.4,1)}\n.ld-dn .cloud{position:absolute;height:12px;border-radius:999px;background:#fffaf0;opacity:.95;transition:transform .7s cubic-bezier(.5,0,.3,1),opacity .5s}\n.ld-dn .cloud::before{content:\"\";position:absolute;left:30%;top:-7px;width:14px;height:14px;border-radius:50%;background:inherit}\n.ld-dn .c1{left:58px;top:14px;width:30px}\n.ld-dn .c2{left:70px;top:27px;width:24px;opacity:.75}\n.ld-dn .star{position:absolute;width:3px;height:3px;border-radius:50%;background:#f4f1de;opacity:0;transform:scale(.2);transition:opacity .5s,transform .6s}\n.ld-dn .s1{left:18px;top:13px}.ld-dn .s2{left:34px;top:30px;width:2px;height:2px}.ld-dn .s3{left:46px;top:12px;width:2px;height:2px}\n.ld-dn[aria-checked=\"true\"]{box-shadow:inset 0 2px 6px rgba(0,0,0,.4),0 12px 26px -12px rgba(61,64,91,.9)}\n.ld-dn[aria-checked=\"true\"]::before{opacity:1}\n.ld-dn[aria-checked=\"true\"] .knob{transform:translateX(58px);background:#f4f1de;box-shadow:0 0 0 6px rgba(244,241,222,.07),0 0 16px rgba(244,241,222,.35)}\n.ld-dn[aria-checked=\"true\"] .knob::after{transform:translate(12px,-2px) scale(1)}\n.ld-dn[aria-checked=\"true\"] .cloud{transform:translateY(34px);opacity:0}\n.ld-dn[aria-checked=\"true\"] .star{opacity:1;transform:scale(1);transition-delay:.25s;animation:ld-dn-twinkle 1.8s ease-in-out infinite}\n.ld-dn[aria-checked=\"true\"] .s2{animation-delay:.6s}\n.ld-dn[aria-checked=\"true\"] .s3{animation-delay:1.1s}\n@keyframes ld-dn-twinkle{0%,100%{opacity:1}50%{opacity:.35}}\n</style>\n<style id=\"css-download\">\n.ld-dl{position:relative;display:inline-grid;place-items:center;width:156px;height:52px;border:0;padding:0;border-radius:26px;background:#e07a5f;color:#141414;cursor:pointer;font:600 14px/1 \"Avenir Next\",\"Segoe UI\",\"Helvetica Neue\",Arial,sans-serif;letter-spacing:.01em;box-shadow:0 12px 26px -12px rgba(224,122,95,.8);transition:width .55s cubic-bezier(.65,0,.35,1),background .45s,box-shadow .45s,transform .2s}\n.ld-dl:active{transform:scale(.97)}\n.ld-dl .lbl{display:inline-flex;align-items:center;gap:9px;white-space:nowrap;transition:opacity .25s,transform .35s}\n.ld-dl .lbl svg{width:16px;height:16px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}\n.ld-dl .ring{position:absolute;left:50%;top:50%;width:52px;height:52px;margin:-26px;overflow:visible;opacity:0;transition:opacity .3s}\n.ld-dl .track,.ld-dl .bar{fill:none;stroke-width:3}\n.ld-dl .track{stroke:rgba(244,241,222,.12)}\n.ld-dl .bar{stroke:#f2cc8f;stroke-linecap:round;stroke-dasharray:145;stroke-dashoffset:145;transform:rotate(-90deg);transform-origin:26px 26px}\n.ld-dl .tick{fill:none;stroke:#141414;stroke-width:3.4;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:30;stroke-dashoffset:30}\n.ld-dl.is-loading{width:52px;background:rgba(224,122,95,0);box-shadow:none}\n.ld-dl.is-loading .lbl{opacity:0;transform:scale(.8)}\n.ld-dl.is-loading .ring{opacity:1;transition-delay:.35s}\n.ld-dl.is-loading .bar{animation:ld-dl-progress 2s cubic-bezier(.5,.05,.3,1) .45s forwards}\n.ld-dl.is-done{width:52px;background:#81b29a;box-shadow:0 12px 26px -12px rgba(129,178,154,.9);animation:ld-dl-pop .5s cubic-bezier(.3,1.6,.5,1)}\n.ld-dl.is-done .lbl{opacity:0}\n.ld-dl.is-done .ring{opacity:1}\n.ld-dl.is-done .track,.ld-dl.is-done .bar{opacity:0}\n.ld-dl.is-done .tick{animation:ld-dl-tick .45s ease-out .1s forwards}\n@keyframes ld-dl-progress{0%{stroke-dashoffset:145}35%{stroke-dashoffset:96}55%{stroke-dashoffset:88}100%{stroke-dashoffset:0}}\n@keyframes ld-dl-tick{to{stroke-dashoffset:0}}\n@keyframes ld-dl-pop{0%{transform:scale(.85)}100%{transform:scale(1)}}\n</style>\n<style id=\"css-skeleton\">\n.ld-skel{width:170px;padding:14px;border-radius:14px;background:#1f1d1c;box-shadow:inset 0 0 0 1px rgba(244,241,222,.06)}\n.ld-skel .row{display:flex;align-items:center;gap:10px;margin-bottom:12px}\n.ld-skel .b{position:relative;display:block;overflow:hidden;background:#2a2826;border-radius:6px}\n.ld-skel .b::after{content:\"\";position:absolute;inset:0;transform:translateX(-100%);background:linear-gradient(90deg,rgba(244,241,222,0),rgba(244,241,222,.1),rgba(244,241,222,0));animation:ld-skel-sweep 1.7s cubic-bezier(.4,0,.2,1) infinite;animation-delay:calc(var(--d) * 1s)}\n.ld-skel .av{width:30px;height:30px;border-radius:50%;flex:none}\n.ld-skel .lines{flex:1;display:grid;gap:6px}\n.ld-skel .l1{height:8px;width:80%}\n.ld-skel .l2{height:7px;width:52%}\n.ld-skel .img{height:44px;margin-bottom:10px;border-radius:9px}\n.ld-skel .l3{height:7px;width:100%;margin-bottom:6px}\n.ld-skel .l4{height:7px;width:66%}\n@keyframes ld-skel-sweep{0%{transform:translateX(-100%)}60%,100%{transform:translateX(100%)}}\n</style>\n</head>\n<body>\n<div class=\"wrap\">\n  <header class=\"masthead\">\n    <div>\n      <p class=\"kicker\"><b aria-hidden=\"true\"></b>An atelier of waiting</p>\n      <h1>Loading,<br><span class=\"nw\"><em>Beautifully</em><span class=\"dots\" aria-hidden=\"true\"><i></i><i></i><i></i></span></span></h1>\n    </div>\n    <div>\n      <p class=\"intro\">A gallery of <strong>16 loaders &amp; micro-interactions</strong>, each drawn in plain CSS and SVG. Press <strong>replay</strong> to watch one from the top, or <strong>copy CSS</strong> to take it home.</p>\n      <div class=\"tools\">\n        <ul class=\"swatches\" aria-label=\"Palette\">\n          <li style=\"--c:#e07a5f\"><span>#e07a5f</span></li>\n          <li style=\"--c:#f2cc8f\"><span>#f2cc8f</span></li>\n          <li style=\"--c:#81b29a\"><span>#81b29a</span></li>\n          <li style=\"--c:#3d405b\"><span>#3d405b</span></li>\n          <li style=\"--c:#f4f1de\"><span>#f4f1de</span></li>\n        </ul>\n        <button type=\"button\" class=\"pill\" id=\"pauseAll\" aria-pressed=\"false\"><svg viewBox=\"0 0 14 14\" aria-hidden=\"true\"><path class=\"pp\" d=\"M4.5 3v8M9.5 3v8\"/></svg><span>Pause all</span></button>\n        <button type=\"button\" class=\"pill\" id=\"replayAll\"><svg viewBox=\"0 0 14 14\" aria-hidden=\"true\"><path d=\"M2.5 7a4.5 4.5 0 1 0 1.4-3.3M2.5 2v2.8h2.8\"/></svg><span>Replay all</span></button>\n      </div>\n    </div>\n  </header>\n\n  <main class=\"gallery\">\n    <h2 class=\"count\" id=\"gallery-h\">16 pieces · CSS &amp; SVG · JavaScript only flips states</h2>\n    <ul class=\"grid\" aria-labelledby=\"gallery-h\">\n\n      <li class=\"card\" data-key=\"blob\" style=\"--accent:#e07a5f\">\n        <div class=\"stage\"><div class=\"ld-blob\" role=\"img\" aria-label=\"A glossy blob slowly morphing its shape\"><span></span></div></div>\n        <div class=\"meta\"><span class=\"num\">01</span><div><h3>Tidal Blob</h3><span class=\"kind\">border-radius morph</span></div>\n          <div class=\"acts\"><button type=\"button\" class=\"act replay\" aria-label=\"Replay Tidal Blob\"><svg viewBox=\"0 0 14 14\" aria-hidden=\"true\"><path d=\"M2.5 7a4.5 4.5 0 1 0 1.4-3.3M2.5 2v2.8h2.8\"/></svg></button><button type=\"button\" class=\"act copy\" aria-label=\"Copy CSS for Tidal Blob\"><svg class=\"ic\" viewBox=\"0 0 14 14\" aria-hidden=\"true\"><path d=\"M5 2.5H4a1.5 1.5 0 0 0-1.5 1.5v1.5L1.5 7l1 1.5V10A1.5 1.5 0 0 0 4 11.5h1M9 2.5h1A1.5 1.5 0 0 1 11.5 4v1.5l1 1.5-1 1.5V10A1.5 1.5 0 0 1 10 11.5H9\"/></svg><svg class=\"ok\" viewBox=\"0 0 14 14\" aria-hidden=\"true\"><path d=\"M3 7.5l2.5 2.5L11 4.5\"/></svg>CSS</button></div></div>\n      </li>\n\n      <li class=\"card\" data-key=\"orbit\" style=\"--accent:#f2cc8f\">\n        <div class=\"stage\"><div class=\"ld-orbit\" role=\"img\" aria-label=\"Three dots orbiting a core, each leaving a fading trail\"><i class=\"o1\"><b></b><b></b><b></b><b></b><b></b></i><i class=\"o2\"><b></b><b></b><b></b><b></b><b></b></i><i class=\"o3\"><b></b><b></b><b></b><b></b><b></b></i><s></s></div></div>\n        <div class=\"meta\"><span class=\"num\">02</span><div><h3>Orbit Trails</h3><span class=\"kind\">staggered rotation</span></div>\n          <div class=\"acts\"><button type=\"button\" class=\"act replay\" aria-label=\"Replay Orbit Trails\"><svg viewBox=\"0 0 14 14\" aria-hidden=\"true\"><path d=\"M2.5 7a4.5 4.5 0 1 0 1.4-3.3M2.5 2v2.8h2.8\"/></svg></button><button type=\"button\" class=\"act copy\" aria-label=\"Copy CSS for Orbit Trails\"><svg class=\"ic\" viewBox=\"0 0 14 14\" aria-hidden=\"true\"><path d=\"M5 2.5H4a1.5 1.5 0 0 0-1.5 1.5v1.5L1.5 7l1 1.5V10A1.5 1.5 0 0 0 4 11.5h1M9 2.5h1A1.5 1.5 0 0 1 11.5 4v1.5l1 1.5-1 1.5V10A1.5 1.5 0 0 1 10 11.5H9\"/></svg><svg class=\"ok\" viewBox=\"0 0 14 14\" aria-hidden=\"true\"><path d=\"M3 7.5l2.5 2.5L11 4.5\"/></svg>CSS</button></div></div>\n      </li>\n\n      <li class=\"card\" data-key=\"check\" style=\"--accent:#81b29a\">\n        <div class=\"stage\"><svg class=\"ld-check\" viewBox=\"0 0 64 64\" role=\"img\" aria-label=\"A pen stroke drawing a circle and a checkmark\"><circle class=\"g\" cx=\"32\" cy=\"32\" r=\"28\"/><circle class=\"c\" cx=\"32\" cy=\"32\" r=\"26\"/><path class=\"k\" d=\"M20 33.5l8 8 16-17\"/></svg></div>\n        <div class=\"meta\"><span class=\"num\">03</span><div><h3>Ink Check</h3><span class=\"kind\">stroke-dashoffset</span></div>\n          <div class=\"acts\"><button type=\"button\" class=\"act replay\" aria-label=\"Replay Ink Check\"><svg viewBox=\"0 0 14 14\" aria-hidden=\"true\"><path d=\"M2.5 7a4.5 4.5 0 1 0 1.4-3.3M2.5 2v2.8h2.8\"/></svg></button><button type=\"button\" class=\"act copy\" aria-label=\"Copy CSS for Ink Check\"><svg class=\"ic\" viewBox=\"0 0 14 14\" aria-hidden=\"true\"><path d=\"M5 2.5H4a1.5 1.5 0 0 0-1.5 1.5v1.5L1.5 7l1 1.5V10A1.5 1.5 0 0 0 4 11.5h1M9 2.5h1A1.5 1.5 0 0 1 11.5 4v1.5l1 1.5-1 1.5V10A1.5 1.5 0 0 1 10 11.5H9\"/></svg><svg class=\"ok\" viewBox=\"0 0 14 14\" aria-hidden=\"true\"><path d=\"M3 7.5l2.5 2.5L11 4.5\"/></svg>CSS</button></div></div>\n      </li>\n\n      <li class=\"card\" data-key=\"fill\" style=\"--accent:#e07a5f\">\n        <div class=\"stage\"><div class=\"ld-fill\" role=\"img\" aria-label=\"A round vessel filling with liquid while a percentage counts up\"><div class=\"glass\"><i class=\"w2\"></i><i class=\"w1\"></i></div><span class=\"pct\"></span></div></div>\n        <div class=\"meta\"><span class=\"num\">04</span><div><h3>Liquid Fill</h3><span class=\"kind\">@property counter</span></div>\n          <div class=\"acts\"><button type=\"button\" class=\"act replay\" aria-label=\"Replay Liquid Fill\"><svg viewBox=\"0 0 14 14\" aria-hidden=\"true\"><path d=\"M2.5 7a4.5 4.5 0 1 0 1.4-3.3M2.5 2v2.8h2.8\"/></svg></button><button type=\"button\" class=\"act copy\" aria-label=\"Copy CSS for Liquid Fill\"><svg class=\"ic\" viewBox=\"0 0 14 14\" aria-hidden=\"true\"><path d=\"M5 2.5H4a1.5 1.5 0 0 0-1.5 1.5v1.5L1.5 7l1 1.5V10A1.5 1.5 0 0 0 4 11.5h1M9 2.5h1A1.5 1.5 0 0 1 11.5 4v1.5l1 1.5-1 1.5V10A1.5 1.5 0 0 1 10 11.5H9\"/></svg><svg class=\"ok\" viewBox=\"0 0 14 14\" aria-hidden=\"true\"><path d=\"M3 7.5l2.5 2.5L11 4.5\"/></svg>CSS</button></div></div>\n      </li>\n\n      <li class=\"card\" data-key=\"fold\" style=\"--accent:#f2cc8f\">\n        <div class=\"stage\"><div class=\"ld-fold\" role=\"img\" aria-label=\"Nine tiles folding over one after another like paper\"><i style=\"--o:0\"></i><i class=\"x\" style=\"--o:1\"></i><i style=\"--o:2\"></i><i class=\"x\" style=\"--o:7\"></i><i style=\"--o:8\"></i><i class=\"x\" style=\"--o:3\"></i><i style=\"--o:6\"></i><i class=\"x\" style=\"--o:5\"></i><i style=\"--o:4\"></i></div></div>\n        <div class=\"meta\"><span class=\"num\">05</span><div><h3>Origami Tiles</h3><span class=\"kind\">3D spiral flips</span></div>\n          <div class=\"acts\"><button type=\"button\" class=\"act replay\" aria-label=\"Replay Origami Tiles\"><svg viewBox=\"0 0 14 14\" aria-hidden=\"true\"><path d=\"M2.5 7a4.5 4.5 0 1 0 1.4-3.3M2.5 2v2.8h2.8\"/></svg></button><button type=\"button\" class=\"act copy\" aria-label=\"Copy CSS for Origami Tiles\"><svg class=\"ic\" viewBox=\"0 0 14 14\" aria-hidden=\"true\"><path d=\"M5 2.5H4a1.5 1.5 0 0 0-1.5 1.5v1.5L1.5 7l1 1.5V10A1.5 1.5 0 0 0 4 11.5h1M9 2.5h1A1.5 1.5 0 0 1 11.5 4v1.5l1 1.5-1 1.5V10A1.5 1.5 0 0 1 10 11.5H9\"/></svg><svg class=\"ok\" viewBox=\"0 0 14 14\" aria-hidden=\"true\"><path d=\"M3 7.5l2.5 2.5L11 4.5\"/></svg>CSS</button></div></div>\n      </li>\n\n      <li class=\"card\" data-key=\"breath\" style=\"--accent:#81b29a\">\n        <div class=\"stage\"><div class=\"ld-breath\" role=\"img\" aria-label=\"A ring that slowly breathes in and out with echo rings\"><i></i><i></i><i></i><span>in</span><span>out</span></div></div>\n        <div class=\"meta\"><span class=\"num\">06</span><div><h3>Breathing Ring</h3><span class=\"kind\">scale + echo</span></div>\n          <div class=\"acts\"><button type=\"button\" class=\"act replay\" aria-label=\"Replay Breathing Ring\"><svg viewBox=\"0 0 14 14\" aria-hidden=\"true\"><path d=\"M2.5 7a4.5 4.5 0 1 0 1.4-3.3M2.5 2v2.8h2.8\"/></svg></button><button type=\"button\" class=\"act copy\" aria-label=\"Copy CSS for Breathing Ring\"><svg class=\"ic\" viewBox=\"0 0 14 14\" aria-hidden=\"true\"><path d=\"M5 2.5H4a1.5 1.5 0 0 0-1.5 1.5v1.5L1.5 7l1 1.5V10A1.5 1.5 0 0 0 4 11.5h1M9 2.5h1A1.5 1.5 0 0 1 11.5 4v1.5l1 1.5-1 1.5V10A1.5 1.5 0 0 1 10 11.5H9\"/></svg><svg class=\"ok\" viewBox=\"0 0 14 14\" aria-hidden=\"true\"><path d=\"M3 7.5l2.5 2.5L11 4.5\"/></svg>CSS</button></div></div>\n      </li>\n\n      <li class=\"card\" data-key=\"helix\" style=\"--accent:#e07a5f\">\n        <div class=\"stage\"><div class=\"ld-helix\" role=\"img\" aria-label=\"A rotating double helix of dots joined by rungs\"><i style=\"--i:0\"><b></b><b></b></i><i style=\"--i:1\"><b></b><b></b></i><i style=\"--i:2\"><b></b><b></b></i><i style=\"--i:3\"><b></b><b></b></i><i style=\"--i:4\"><b></b><b></b></i><i style=\"--i:5\"><b></b><b></b></i><i style=\"--i:6\"><b></b><b></b></i><i style=\"--i:7\"><b></b><b></b></i><i style=\"--i:8\"><b></b><b></b></i><i style=\"--i:9\"><b></b><b></b></i><i style=\"--i:10\"><b></b><b></b></i><i style=\"--i:11\"><b></b><b></b></i></div></div>\n        <div class=\"meta\"><span class=\"num\">07</span><div><h3>Helix</h3><span class=\"kind\">phase delays</span></div>\n          <div class=\"acts\"><button type=\"button\" class=\"act replay\" aria-label=\"Replay Helix\"><svg viewBox=\"0 0 14 14\" aria-hidden=\"true\"><path d=\"M2.5 7a4.5 4.5 0 1 0 1.4-3.3M2.5 2v2.8h2.8\"/></svg></button><button type=\"button\" class=\"act copy\" aria-label=\"Copy CSS for Helix\"><svg class=\"ic\" viewBox=\"0 0 14 14\" aria-hidden=\"true\"><path d=\"M5 2.5H4a1.5 1.5 0 0 0-1.5 1.5v1.5L1.5 7l1 1.5V10A1.5 1.5 0 0 0 4 11.5h1M9 2.5h1A1.5 1.5 0 0 1 11.5 4v1.5l1 1.5-1 1.5V10A1.5 1.5 0 0 1 10 11.5H9\"/></svg><svg class=\"ok\" viewBox=\"0 0 14 14\" aria-hidden=\"true\"><path d=\"M3 7.5l2.5 2.5L11 4.5\"/></svg>CSS</button></div></div>\n      </li>\n\n      <li class=\"card\" data-key=\"type\" style=\"--accent:#f4f1de\">\n        <div class=\"stage\"><div class=\"ld-type\" role=\"img\" aria-label=\"The word loading typed out with an ellipsis and a blinking caret\"><span class=\"t\">loading</span><span class=\"d\">...</span><span class=\"caret\"></span></div></div>\n        <div class=\"meta\"><span class=\"num\">08</span><div><h3>Typewriter</h3><span class=\"kind\">steps() + ch</span></div>\n          <div class=\"acts\"><button type=\"button\" class=\"act replay\" aria-label=\"Replay Typewriter\"><svg viewBox=\"0 0 14 14\" aria-hidden=\"true\"><path d=\"M2.5 7a4.5 4.5 0 1 0 1.4-3.3M2.5 2v2.8h2.8\"/></svg></button><button type=\"button\" class=\"act copy\" aria-label=\"Copy CSS for Typewriter\"><svg class=\"ic\" viewBox=\"0 0 14 14\" aria-hidden=\"true\"><path d=\"M5 2.5H4a1.5 1.5 0 0 0-1.5 1.5v1.5L1.5 7l1 1.5V10A1.5 1.5 0 0 0 4 11.5h1M9 2.5h1A1.5 1.5 0 0 1 11.5 4v1.5l1 1.5-1 1.5V10A1.5 1.5 0 0 1 10 11.5H9\"/></svg><svg class=\"ok\" viewBox=\"0 0 14 14\" aria-hidden=\"true\"><path d=\"M3 7.5l2.5 2.5L11 4.5\"/></svg>CSS</button></div></div>\n      </li>\n\n      <li class=\"card\" data-key=\"pendulum\" style=\"--accent:#f2cc8f\">\n        <div class=\"stage\"><div class=\"ld-pend\" role=\"img\" aria-label=\"A pendulum swinging with its shadow tracking below\"><svg class=\"arc\" viewBox=\"0 0 130 112\" aria-hidden=\"true\"><path d=\"M22.1 67.1A73 73 0 0 0 107.9 67.1\"/></svg><span class=\"pivot\"></span><div class=\"arm\"><span class=\"bob\"></span></div><span class=\"shadow\"></span></div></div>\n        <div class=\"meta\"><span class=\"num\">09</span><div><h3>Pendulum</h3><span class=\"kind\">translate + scale</span></div>\n          <div class=\"acts\"><button type=\"button\" class=\"act replay\" aria-label=\"Replay Pendulum\"><svg viewBox=\"0 0 14 14\" aria-hidden=\"true\"><path d=\"M2.5 7a4.5 4.5 0 1 0 1.4-3.3M2.5 2v2.8h2.8\"/></svg></button><button type=\"button\" class=\"act copy\" aria-label=\"Copy CSS for Pendulum\"><svg class=\"ic\" viewBox=\"0 0 14 14\" aria-hidden=\"true\"><path d=\"M5 2.5H4a1.5 1.5 0 0 0-1.5 1.5v1.5L1.5 7l1 1.5V10A1.5 1.5 0 0 0 4 11.5h1M9 2.5h1A1.5 1.5 0 0 1 11.5 4v1.5l1 1.5-1 1.5V10A1.5 1.5 0 0 1 10 11.5H9\"/></svg><svg class=\"ok\" viewBox=\"0 0 14 14\" aria-hidden=\"true\"><path d=\"M3 7.5l2.5 2.5L11 4.5\"/></svg>CSS</button></div></div>\n      </li>\n\n      <li class=\"card\" data-key=\"comet\" style=\"--accent:#e07a5f\">\n        <div class=\"stage\"><div class=\"ld-comet\" role=\"img\" aria-label=\"A gradient spinner whose bright head drags a comet tail\"><i></i><b></b></div></div>\n        <div class=\"meta\"><span class=\"num\">10</span><div><h3>Comet</h3><span class=\"kind\">conic + mask</span></div>\n          <div class=\"acts\"><button type=\"button\" class=\"act replay\" aria-label=\"Replay Comet\"><svg viewBox=\"0 0 14 14\" aria-hidden=\"true\"><path d=\"M2.5 7a4.5 4.5 0 1 0 1.4-3.3M2.5 2v2.8h2.8\"/></svg></button><button type=\"button\" class=\"act copy\" aria-label=\"Copy CSS for Comet\"><svg class=\"ic\" viewBox=\"0 0 14 14\" aria-hidden=\"true\"><path d=\"M5 2.5H4a1.5 1.5 0 0 0-1.5 1.5v1.5L1.5 7l1 1.5V10A1.5 1.5 0 0 0 4 11.5h1M9 2.5h1A1.5 1.5 0 0 1 11.5 4v1.5l1 1.5-1 1.5V10A1.5 1.5 0 0 1 10 11.5H9\"/></svg><svg class=\"ok\" viewBox=\"0 0 14 14\" aria-hidden=\"true\"><path d=\"M3 7.5l2.5 2.5L11 4.5\"/></svg>CSS</button></div></div>\n      </li>\n\n      <li class=\"card\" data-key=\"pixels\" style=\"--accent:#81b29a\">\n        <div class=\"stage\"><div class=\"ld-pix\" role=\"img\" aria-label=\"A grid of pixels rippling in a diagonal wave\">\n          <i style=\"--x:0;--y:0\"></i><i style=\"--x:1;--y:0\"></i><i style=\"--x:2;--y:0\"></i><i style=\"--x:3;--y:0\"></i><i style=\"--x:4;--y:0\"></i><i style=\"--x:5;--y:0\"></i><i style=\"--x:6;--y:0\"></i><i style=\"--x:7;--y:0\"></i>\n          <i style=\"--x:0;--y:1\"></i><i style=\"--x:1;--y:1\"></i><i style=\"--x:2;--y:1\"></i><i style=\"--x:3;--y:1\"></i><i style=\"--x:4;--y:1\"></i><i style=\"--x:5;--y:1\"></i><i style=\"--x:6;--y:1\"></i><i style=\"--x:7;--y:1\"></i>\n          <i style=\"--x:0;--y:2\"></i><i style=\"--x:1;--y:2\"></i><i style=\"--x:2;--y:2\"></i><i style=\"--x:3;--y:2\"></i><i style=\"--x:4;--y:2\"></i><i style=\"--x:5;--y:2\"></i><i style=\"--x:6;--y:2\"></i><i style=\"--x:7;--y:2\"></i>\n          <i style=\"--x:0;--y:3\"></i><i style=\"--x:1;--y:3\"></i><i style=\"--x:2;--y:3\"></i><i style=\"--x:3;--y:3\"></i><i style=\"--x:4;--y:3\"></i><i style=\"--x:5;--y:3\"></i><i style=\"--x:6;--y:3\"></i><i style=\"--x:7;--y:3\"></i>\n        </div></div>\n        <div class=\"meta\"><span class=\"num\">11</span><div><h3>Pixel Wave</h3><span class=\"kind\">diagonal stagger</span></div>\n          <div class=\"acts\"><button type=\"button\" class=\"act replay\" aria-label=\"Replay Pixel Wave\"><svg viewBox=\"0 0 14 14\" aria-hidden=\"true\"><path d=\"M2.5 7a4.5 4.5 0 1 0 1.4-3.3M2.5 2v2.8h2.8\"/></svg></button><button type=\"button\" class=\"act copy\" aria-label=\"Copy CSS for Pixel Wave\"><svg class=\"ic\" viewBox=\"0 0 14 14\" aria-hidden=\"true\"><path d=\"M5 2.5H4a1.5 1.5 0 0 0-1.5 1.5v1.5L1.5 7l1 1.5V10A1.5 1.5 0 0 0 4 11.5h1M9 2.5h1A1.5 1.5 0 0 1 11.5 4v1.5l1 1.5-1 1.5V10A1.5 1.5 0 0 1 10 11.5H9\"/></svg><svg class=\"ok\" viewBox=\"0 0 14 14\" aria-hidden=\"true\"><path d=\"M3 7.5l2.5 2.5L11 4.5\"/></svg>CSS</button></div></div>\n      </li>\n\n      <li class=\"card\" data-key=\"book\" style=\"--accent:#f4f1de\">\n        <div class=\"stage\"><div class=\"ld-book\" role=\"img\" aria-label=\"An open book with pages turning one after another\"><span class=\"l\"></span><span class=\"r\"></span><b></b><b></b><b></b></div></div>\n        <div class=\"meta\"><span class=\"num\">12</span><div><h3>Page Flip</h3><span class=\"kind\">rotateY in 3D</span></div>\n          <div class=\"acts\"><button type=\"button\" class=\"act replay\" aria-label=\"Replay Page Flip\"><svg viewBox=\"0 0 14 14\" aria-hidden=\"true\"><path d=\"M2.5 7a4.5 4.5 0 1 0 1.4-3.3M2.5 2v2.8h2.8\"/></svg></button><button type=\"button\" class=\"act copy\" aria-label=\"Copy CSS for Page Flip\"><svg class=\"ic\" viewBox=\"0 0 14 14\" aria-hidden=\"true\"><path d=\"M5 2.5H4a1.5 1.5 0 0 0-1.5 1.5v1.5L1.5 7l1 1.5V10A1.5 1.5 0 0 0 4 11.5h1M9 2.5h1A1.5 1.5 0 0 1 11.5 4v1.5l1 1.5-1 1.5V10A1.5 1.5 0 0 1 10 11.5H9\"/></svg><svg class=\"ok\" viewBox=\"0 0 14 14\" aria-hidden=\"true\"><path d=\"M3 7.5l2.5 2.5L11 4.5\"/></svg>CSS</button></div></div>\n      </li>\n\n      <li class=\"card\" data-key=\"heart\" style=\"--accent:#e07a5f\">\n        <div class=\"stage\"><button type=\"button\" class=\"ld-heart\" aria-pressed=\"false\" aria-label=\"Like\"><svg viewBox=\"0 0 32 32\" aria-hidden=\"true\"><path d=\"M16 27.5S4 20.2 4 11.8A6.1 6.1 0 0 1 16 9.4a6.1 6.1 0 0 1 12 2.4C28 20.2 16 27.5 16 27.5Z\"/></svg><i style=\"--a:0deg\"></i><i style=\"--a:45deg\"></i><i style=\"--a:90deg\"></i><i style=\"--a:135deg\"></i><i style=\"--a:180deg\"></i><i style=\"--a:225deg\"></i><i style=\"--a:270deg\"></i><i style=\"--a:315deg\"></i><s></s></button></div>\n        <div class=\"meta\"><span class=\"num\">13</span><div><h3>Elastic Heart</h3><span class=\"kind\">click to like</span></div>\n          <div class=\"acts\"><button type=\"button\" class=\"act replay\" aria-label=\"Replay Elastic Heart\"><svg viewBox=\"0 0 14 14\" aria-hidden=\"true\"><path d=\"M2.5 7a4.5 4.5 0 1 0 1.4-3.3M2.5 2v2.8h2.8\"/></svg></button><button type=\"button\" class=\"act copy\" aria-label=\"Copy CSS for Elastic Heart\"><svg class=\"ic\" viewBox=\"0 0 14 14\" aria-hidden=\"true\"><path d=\"M5 2.5H4a1.5 1.5 0 0 0-1.5 1.5v1.5L1.5 7l1 1.5V10A1.5 1.5 0 0 0 4 11.5h1M9 2.5h1A1.5 1.5 0 0 1 11.5 4v1.5l1 1.5-1 1.5V10A1.5 1.5 0 0 1 10 11.5H9\"/></svg><svg class=\"ok\" viewBox=\"0 0 14 14\" aria-hidden=\"true\"><path d=\"M3 7.5l2.5 2.5L11 4.5\"/></svg>CSS</button></div></div>\n      </li>\n\n      <li class=\"card\" data-key=\"daynight\" style=\"--accent:#f2cc8f\">\n        <div class=\"stage\"><button type=\"button\" class=\"ld-dn\" role=\"switch\" aria-checked=\"false\" aria-label=\"Night mode\"><span class=\"cloud c1\"></span><span class=\"cloud c2\"></span><span class=\"star s1\"></span><span class=\"star s2\"></span><span class=\"star s3\"></span><span class=\"knob\"></span></button></div>\n        <div class=\"meta\"><span class=\"num\">14</span><div><h3>Day / Night</h3><span class=\"kind\">click to toggle</span></div>\n          <div class=\"acts\"><button type=\"button\" class=\"act replay\" aria-label=\"Replay Day / Night\"><svg viewBox=\"0 0 14 14\" aria-hidden=\"true\"><path d=\"M2.5 7a4.5 4.5 0 1 0 1.4-3.3M2.5 2v2.8h2.8\"/></svg></button><button type=\"button\" class=\"act copy\" aria-label=\"Copy CSS for Day / Night\"><svg class=\"ic\" viewBox=\"0 0 14 14\" aria-hidden=\"true\"><path d=\"M5 2.5H4a1.5 1.5 0 0 0-1.5 1.5v1.5L1.5 7l1 1.5V10A1.5 1.5 0 0 0 4 11.5h1M9 2.5h1A1.5 1.5 0 0 1 11.5 4v1.5l1 1.5-1 1.5V10A1.5 1.5 0 0 1 10 11.5H9\"/></svg><svg class=\"ok\" viewBox=\"0 0 14 14\" aria-hidden=\"true\"><path d=\"M3 7.5l2.5 2.5L11 4.5\"/></svg>CSS</button></div></div>\n      </li>\n\n      <li class=\"card\" data-key=\"download\" style=\"--accent:#81b29a\">\n        <div class=\"stage\"><button type=\"button\" class=\"ld-dl\" aria-label=\"Download file\"><span class=\"lbl\"><svg viewBox=\"0 0 16 16\" aria-hidden=\"true\"><path d=\"M8 2.5v8M4.5 7.5 8 11l3.5-3.5M3 13.5h10\"/></svg>Download</span><svg class=\"ring\" viewBox=\"0 0 52 52\" aria-hidden=\"true\"><circle class=\"track\" cx=\"26\" cy=\"26\" r=\"23\"/><circle class=\"bar\" cx=\"26\" cy=\"26\" r=\"23\"/><path class=\"tick\" d=\"M17 26.5l6 6 12-13\"/></svg></button></div>\n        <div class=\"meta\"><span class=\"num\">15</span><div><h3>Download → Done</h3><span class=\"kind\">click to run</span></div>\n          <div class=\"acts\"><button type=\"button\" class=\"act replay\" aria-label=\"Replay Download to Done\"><svg viewBox=\"0 0 14 14\" aria-hidden=\"true\"><path d=\"M2.5 7a4.5 4.5 0 1 0 1.4-3.3M2.5 2v2.8h2.8\"/></svg></button><button type=\"button\" class=\"act copy\" aria-label=\"Copy CSS for Download to Done\"><svg class=\"ic\" viewBox=\"0 0 14 14\" aria-hidden=\"true\"><path d=\"M5 2.5H4a1.5 1.5 0 0 0-1.5 1.5v1.5L1.5 7l1 1.5V10A1.5 1.5 0 0 0 4 11.5h1M9 2.5h1A1.5 1.5 0 0 1 11.5 4v1.5l1 1.5-1 1.5V10A1.5 1.5 0 0 1 10 11.5H9\"/></svg><svg class=\"ok\" viewBox=\"0 0 14 14\" aria-hidden=\"true\"><path d=\"M3 7.5l2.5 2.5L11 4.5\"/></svg>CSS</button></div></div>\n      </li>\n\n      <li class=\"card\" data-key=\"skeleton\" style=\"--accent:#f4f1de\">\n        <div class=\"stage\"><div class=\"ld-skel\" role=\"img\" aria-label=\"A placeholder card with a shimmer sweeping across it\"><div class=\"row\"><span class=\"b av\" style=\"--d:0\"></span><span class=\"lines\"><span class=\"b l1\" style=\"--d:.08\"></span><span class=\"b l2\" style=\"--d:.08\"></span></span></div><span class=\"b img\" style=\"--d:.03\"></span><span class=\"b l3\" style=\"--d:.03\"></span><span class=\"b l4\" style=\"--d:0\"></span></div></div>\n        <div class=\"meta\"><span class=\"num\">16</span><div><h3>Skeleton Shimmer</h3><span class=\"kind\">sweeping highlight</span></div>\n          <div class=\"acts\"><button type=\"button\" class=\"act replay\" aria-label=\"Replay Skeleton Shimmer\"><svg viewBox=\"0 0 14 14\" aria-hidden=\"true\"><path d=\"M2.5 7a4.5 4.5 0 1 0 1.4-3.3M2.5 2v2.8h2.8\"/></svg></button><button type=\"button\" class=\"act copy\" aria-label=\"Copy CSS for Skeleton Shimmer\"><svg class=\"ic\" viewBox=\"0 0 14 14\" aria-hidden=\"true\"><path d=\"M5 2.5H4a1.5 1.5 0 0 0-1.5 1.5v1.5L1.5 7l1 1.5V10A1.5 1.5 0 0 0 4 11.5h1M9 2.5h1A1.5 1.5 0 0 1 11.5 4v1.5l1 1.5-1 1.5V10A1.5 1.5 0 0 1 10 11.5H9\"/></svg><svg class=\"ok\" viewBox=\"0 0 14 14\" aria-hidden=\"true\"><path d=\"M3 7.5l2.5 2.5L11 4.5\"/></svg>CSS</button></div></div>\n      </li>\n    </ul>\n  </main>\n\n  <footer class=\"footnote\">\n    <span>Loading, Beautifully · an original study in patience</span>\n    <span>Every loader: pure CSS &amp; inline SVG</span>\n  </footer>\n</div>\n\n<div class=\"toast\" id=\"toast\" role=\"status\" aria-live=\"polite\"><i aria-hidden=\"true\"><svg viewBox=\"0 0 12 12\"><path d=\"M2.5 6.3 5 8.6l4.5-5\"/></svg></i><span id=\"toastMsg\">Copied</span></div>\n\n<dialog id=\"codeDlg\" aria-labelledby=\"dlgTitle\">\n  <h2 id=\"dlgTitle\">Copy this CSS</h2>\n  <p>Your browser blocked clipboard access here, so the code is selected for you. Press Ctrl+C or ⌘+C.</p>\n  <textarea id=\"dlgCode\" readonly aria-label=\"CSS source\"></textarea>\n  <div class=\"row\"><button type=\"button\" class=\"pill\" id=\"dlgClose\">Close</button></div>\n</dialog>\n\n<script>\n(() => {\n  'use strict';\n  const grid = document.querySelector('.grid');\n  const cards = [...document.querySelectorAll('.card')];\n  const toast = document.getElementById('toast');\n  const toastMsg = document.getElementById('toastMsg');\n  const rmq = window.matchMedia ? matchMedia('(prefers-reduced-motion: reduce)') : { matches: false };\n\n  /* ---------- helpers ---------- */\n  function dedent(text) {\n    const lines = text.replace(/\\t/g, '  ').split('\\n');\n    while (lines.length && !lines[0].trim()) lines.shift();\n    while (lines.length && !lines[lines.length - 1].trim()) lines.pop();\n    const ind = Math.min(...lines.filter(l => l.trim()).map(l => l.match(/^ */)[0].length));\n    return lines.map(l => l.slice(ind)).join('\\n');\n  }\n  let toastT = 0;\n  function say(msg, sub) {\n    toastMsg.innerHTML = '';\n    toastMsg.append(msg);\n    if (sub) { const s = document.createElement('small'); s.textContent = sub; toastMsg.append(s); }\n    toast.classList.add('on');\n    clearTimeout(toastT);\n    toastT = setTimeout(() => toast.classList.remove('on'), 2200);\n  }\n\n  /* ---------- replay: swap in a fresh clone so every animation starts from zero ---------- */\n  function replay(card) {\n    const stage = card.querySelector('.stage');\n    const old = stage.firstElementChild;\n    const fresh = old.cloneNode(true);\n    fresh.classList.remove('is-loading', 'is-done', 'was');\n    if (fresh.hasAttribute('aria-pressed')) fresh.setAttribute('aria-pressed', 'false');\n    if (fresh.getAttribute('role') === 'switch') fresh.setAttribute('aria-checked', 'false');\n    stage.replaceChild(fresh, old);\n    const key = card.dataset.key;\n    if (key === 'download') { clearTimeout(dlTimer); dlUser = false; dlTimer = setTimeout(() => runDownload(fresh, true), 500); }\n    if (key === 'daynight') { dnUser = false; }\n  }\n\n  /* ---------- copy CSS ---------- */\n  async function copyCSS(card, btn) {\n    const key = card.dataset.key;\n    const styleEl = document.getElementById('css-' + key);\n    if (!styleEl) return;\n    const title = card.querySelector('h3').textContent;\n    const markup = card.querySelector('.stage').innerHTML.trim().replace(/\\s+/g, ' ').replace(/> </g, '><');\n    const css = '/* ' + title + ' — from \"Loading, Beautifully\"\\n   markup: ' + markup.replace(/\\*\\//g, '* /') + ' */\\n' + dedent(styleEl.textContent) + '\\n';\n    const lines = css.split('\\n').length;\n    const ok = () => {\n      btn.classList.add('done');\n      setTimeout(() => btn.classList.remove('done'), 1500);\n      say('Copied ' + title + ' CSS', lines + ' lines');\n    };\n    try {\n      if (navigator.clipboard && window.isSecureContext !== false) {\n        await navigator.clipboard.writeText(css);\n        ok(); return;\n      }\n      throw new Error('no clipboard');\n    } catch (e) {\n      // legacy path\n      try {\n        const ta = document.createElement('textarea');\n        ta.value = css; ta.setAttribute('readonly', '');\n        ta.style.position = 'fixed'; ta.style.opacity = '0'; ta.style.left = '-9999px';\n        document.body.appendChild(ta); ta.select();\n        const done = document.execCommand && document.execCommand('copy');\n        ta.remove();\n        if (done) { ok(); return; }\n      } catch (e2) { /* fall through */ }\n      openDialog(css);\n    }\n  }\n  const dlg = document.getElementById('codeDlg');\n  const dlgCode = document.getElementById('dlgCode');\n  function openDialog(css) {\n    dlgCode.value = css;\n    try { dlg.showModal(); } catch (e) { dlg.setAttribute('open', ''); }\n    dlgCode.focus(); dlgCode.select();\n  }\n  document.getElementById('dlgClose').addEventListener('click', () => { try { dlg.close(); } catch (e) { dlg.removeAttribute('open'); } });\n\n  /* ---------- one delegated click handler for the whole gallery ---------- */\n  grid.addEventListener('click', e => {\n    const t = e.target;\n    const card = t.closest('.card');\n    if (!card) return;\n    const act = t.closest('.act');\n    if (act && act.classList.contains('replay')) { replay(card); return; }\n    if (act && act.classList.contains('copy')) { copyCSS(card, act); return; }\n    const heart = t.closest('.ld-heart');\n    if (heart) {\n      const on = heart.getAttribute('aria-pressed') !== 'true';\n      heart.classList.add('was');\n      heart.setAttribute('aria-pressed', String(on));\n      heart.setAttribute('aria-label', on ? 'Liked' : 'Like');\n      return;\n    }\n    const dn = t.closest('.ld-dn');\n    if (dn) { dnUser = true; toggleDN(dn); return; }\n    const dl = t.closest('.ld-dl');\n    if (dl) { dlUser = true; runDownload(dl, false); }\n  });\n\n  /* ---------- day / night: flips on click; demos itself until touched ---------- */\n  let dnUser = false;\n  function toggleDN(el) {\n    const on = el.getAttribute('aria-checked') !== 'true';\n    el.setAttribute('aria-checked', String(on));\n  }\n  setInterval(() => {\n    if (dnUser || document.hidden || rmq.matches || document.body.classList.contains('all-paused')) return;\n    const el = document.querySelector('.ld-dn');\n    if (el) toggleDN(el);\n  }, 2600);\n\n  /* ---------- download: idle -> loading ring -> done tick -> idle ---------- */\n  let dlTimer = 0, dlUser = false;\n  function runDownload(el, demo) {\n    if (el.classList.contains('is-loading') || el.classList.contains('is-done')) return;\n    clearTimeout(dlTimer);\n    el.classList.add('is-loading');\n    el.setAttribute('aria-label', 'Downloading');\n    const bar = el.querySelector('.bar');\n    const onEnd = ev => {\n      if (ev.animationName !== 'ld-dl-progress') return;\n      bar.removeEventListener('animationend', onEnd);\n      el.classList.remove('is-loading');\n      el.classList.add('is-done');\n      el.setAttribute('aria-label', 'Downloaded');\n      dlTimer = setTimeout(() => {\n        el.classList.remove('is-done');\n        el.setAttribute('aria-label', 'Download file');\n        if (!dlUser && !rmq.matches) dlTimer = setTimeout(() => { if (el.isConnected) runDownload(el, true); }, 2200);\n      }, 1800);\n    };\n    bar.addEventListener('animationend', onEnd);\n  }\n  const dlEl = document.querySelector('.ld-dl');\n  if (dlEl && !rmq.matches) dlTimer = setTimeout(() => runDownload(dlEl, true), 900);\n\n  /* ---------- global controls ---------- */\n  const pauseAll = document.getElementById('pauseAll');\n  pauseAll.addEventListener('click', () => {\n    const on = !document.body.classList.contains('all-paused');\n    document.body.classList.toggle('all-paused', on);\n    pauseAll.setAttribute('aria-pressed', String(on));\n    pauseAll.querySelector('span').textContent = on ? 'Resume all' : 'Pause all';\n    pauseAll.querySelector('.pp').setAttribute('d', on ? 'M4.5 3l6 4-6 4Z' : 'M4.5 3v8M9.5 3v8');\n  });\n  document.getElementById('replayAll').addEventListener('click', () => {\n    cards.forEach((c, i) => setTimeout(() => replay(c), i * 45));\n  });\n\n  /* ---------- pause stages that are off-screen ---------- */\n  if ('IntersectionObserver' in window) {\n    const io = new IntersectionObserver(entries => {\n      entries.forEach(en => en.target.classList.toggle('off', !en.isIntersecting));\n    }, { rootMargin: '80px' });\n    document.querySelectorAll('.stage').forEach(s => io.observe(s));\n  }\n})();\n</script>\n</body>\n</html>\n";
